/// 解析并求值一步完成
///
/// 等价于 [`Expression`] 的 [`FromStr`] 解析后调用 [`Expression::evaluate`], 适合一次性求值;
/// 需要对同一表达式使用不同上下文多次求值时, 请使用 [`Expression`].
///
/// # Examples
///
/// ```
/// use expression::{Error, EvaluationContext, EvaluationError, Value, evaluate};
///
/// /// 调用者提供的上下文: 变量与函数
/// struct Ctx;
///
/// impl EvaluationContext for Ctx {
///     fn get_variable(&self, name: &str) -> Option<Value> {
///         match name {
///             "hp" => Some(Value::from(70)),
///             "name" => Some(Value::from("主角")),
///             _ => None,
///         }
///     }
///
///     fn call_function(&self, name: &str, arguments: &[Value]) -> Result<Value, EvaluationError> {
///         match name {
///             "random" => Ok(Value::from(3)), // random 的语义由调用者决定
///             _ => Err(EvaluationError::UnknownFunction(name.into())),
///         }
///     }
/// }
///
/// # fn main() -> Result<(), Error> {
/// assert_eq!(evaluate("hp - 30", &Ctx)?, Value::from(40));
/// assert_eq!(evaluate("name + \"先生\"", &Ctx)?, Value::from("主角先生"));
/// assert_eq!(evaluate("hp > 0 && name != \"\"", &Ctx)?, Value::from(true));
/// assert_eq!(evaluate("random(1, 10)", &Ctx)?, Value::from(3));
/// # Ok(())
/// # }
/// ```
pub fn evaluate(source: &str, context: &dyn EvaluationContext) -> Result<Value> {
    Expression::from_str(source)?
        .evaluate(context)
        .map_err(Error::Evaluation)
}

/// 无上下文求值
///
/// 表达式只能使用字面量与运算符, 引用变量或调用函数时返回 `None`.
pub fn evaluate_constantly(source: &str) -> Option<Value> {
    Expression::from_str(source)
        .ok()?
        .evaluate(&EmptyEvaluationContext)
        .ok()
}
